-- 학교 학년별 학급수·재학생 수 **이관 백필**(F-22·F-23). 원천: 레거시 `DSLab.schAllData`.
--
-- ★학교코드가 그대로 맞는다 — 레거시 2,280행 중 **2,277행이 우리 schools.school_code 와 일치**
--   (실측 2026-11-09, 99.9%). 이름도 같다(우리는 '…고등학교' 접미어를 떼고 저장).
--   남는 3곳(57013 한국K-POP고 · 30030 동우여고 · 76038 간디고)은 우리 마스터에 없는 학교다 —
--   없는 학교를 만들지 않는다(근거 없는 행을 넣으면 학교 목록이 레거시와 달라진다).
--
-- ‼️**UPDATE 만 한다.** 매칭되는 학교의 빈 칸을 채울 뿐, 행을 만들거나 지우지 않는다.
--   같은 파일을 두 번 돌려도 결과가 같다(같은 값으로 덮는다).
--
-- ★왜 마이그레이션에 데이터를 넣는가 — 이 값은 담당자가 손으로 넣을 수 있는 양이 아니고
--   (2,277곳 × 6칸), 레거시가 유일한 원천이다. 화면에서 고칠 수는 있다(거래처·학교 관리).

CREATE TEMPORARY TABLE tmp_sch_cnt (
    school_code VARCHAR(50) NOT NULL PRIMARY KEY,
    c1 INT, s1 INT, c2 INT, s2 INT, c3 INT, s3 INT
) ENGINE=InnoDB;






UPDATE schools s
    JOIN tmp_sch_cnt t ON t.school_code = s.school_code
SET s.cls1_class_cnt = t.c1, s.cls1_student_cnt = t.s1,
    s.cls2_class_cnt = t.c2, s.cls2_student_cnt = t.s2,
    s.cls3_class_cnt = t.c3, s.cls3_student_cnt = t.s3;

DROP TEMPORARY TABLE tmp_sch_cnt;
